def search_wikipedia(query, limit=10, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, client_id, api_key_id, status, latency_ms, meta=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(6)}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": now_iso,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _validate():
        if not isinstance(query, str) or not query.strip():
            return _err("VALIDATION_ERROR", "query must be a non-empty string.")
        if not isinstance(limit, int) or limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be a positive integer.")
        # schema says tool truncates; search_queries constraint says between 1 and 50
        if limit > 50:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50.")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _pick_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        # Prefer active key for an active client
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            c = next((x for x in active_clients if x.get("id") == cid), None)
            if c:
                return c, k
        # Fall back to ambient/internal call without key for some active client
        return active_clients[0], None

    def _enforce_quota(client_row, endpoint_name):
        # total successful tool calls per UTC day must not exceed daily_request_limit
        # Use request_logs.json as authoritative audit log if present; otherwise fall back to search_queries+derived_artifacts.
        limit_daily = client_row.get("daily_request_limit")
        if not isinstance(limit_daily, int) or limit_daily < 0:
            # treat invalid config as unauthorized service condition
            return _err("UNAUTHORIZED", "Client is not configured with a valid daily_request_limit.")
        day = _utc_day(now)

        total_success = 0
        logs = _load("request_logs.json")
        if isinstance(logs, list) and logs:
            for r in logs:
                if r.get("client_id") != client_row.get("id"):
                    continue
                ts = _parse_dt(r.get("ts"))
                if not ts or _utc_day(ts) != day:
                    continue
                if r.get("status") == "succeeded":
                    total_success += 1
        else:
            # fallback: count succeeded search_queries and available derived_artifacts computed today
            sq = _load("search_queries.json")
            if isinstance(sq, list):
                for r in sq:
                    if r.get("client_id") != client_row.get("id"):
                        continue
                    ts = _parse_dt(r.get("requested_at"))
                    if ts and _utc_day(ts) == day and r.get("status") == "succeeded":
                        total_success += 1
            da = _load("derived_artifacts.json")
            if isinstance(da, list):
                for r in da:
                    if r.get("client_id") != client_row.get("id"):
                        continue
                    ts = _parse_dt(r.get("computed_at")) or _parse_dt(r.get("updated_at"))
                    if ts and _utc_day(ts) == day and r.get("status") == "available":
                        total_success += 1

        if total_success >= limit_daily:
            return _err("QUOTA_EXCEEDED", f"Rate limited: daily quota exceeded for client_id {client_row.get('id')}.",
                        client_id=client_row.get("id"), daily_request_limit=limit_daily, day=day, successful_calls=total_success)
        return None

    # ---- validate first ----
    v = _validate()
    if v:
        _log("search_wikipedia", None, None, "failed", (time.time() - started) * 1000, {"error": v["error"]})
        return v

    client, key = _pick_context()
    if not client:
        e = _err("UNAUTHORIZED", "No active API client is available for this request.")
        _log("search_wikipedia", None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # enforce key rule (if key used, must be active and client active)
    if key and key.get("status") != "active":
        e = _err("UNAUTHORIZED", "Rejected: API key is inactive or expired for this client.", api_key_id=key.get("id"))
        _log("search_wikipedia", client.get("id"), key.get("id"), "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # quota before doing work (based on successful calls so far today)
    qerr = _enforce_quota(client, "search_wikipedia")
    if qerr:
        # still log the refused call
        _log("search_wikipedia", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": qerr["error"]})
        return qerr

    # ---- create search_queries row and transition queued->running->succeeded/failed ----
    searches = _load("search_queries.json")
    if not isinstance(searches, list):
        searches = []

    def _new_id():
        return f"wiki_srq_{secrets.token_hex(12)}"

    language = client.get("default_language") if isinstance(client.get("default_language"), str) and client.get("default_language") else "en"
    srq = {
        "id": _new_id(),
        "client_id": client.get("id"),
        "api_key_id": key.get("id") if key else None,
        "language": language,
        "query": query,
        "limit": int(limit),
        "status": "queued",
        "result_count": None,
        "results": None,
        "error_message": None,
        "requested_at": now_iso,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    searches.append(srq)
    try:
        _save("search_queries.json", searches)
    except Exception:
        e = _err("CONFLICT", "Failed to persist search query job.")
        _log("search_wikipedia", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    def _update_job(fields):
        nonlocal searches, srq
        # reload and update by id to avoid stale list issues
        searches = _load("search_queries.json")
        if not isinstance(searches, list):
            searches = []
        job = next((r for r in searches if r.get("id") == srq["id"]), None)
        if not job:
            return False
        job.update(fields)
        job["updated_at"] = now_iso
        try:
            _save("search_queries.json", searches)
            srq = job
            return True
        except Exception:
            return False

    # queued->running
    _update_job({"status": "running"})

    # Offline behaviour: serve deterministic "search" results from cached articles for the chosen language.
    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []

    qnorm = re.sub(r"\s+", " ", query.strip()).lower()
    qtokens = [t for t in re.split(r"[\s\-_:/,.;()]+", qnorm) if t]
    def _score(art):
        title = (art.get("title") or "").lower()
        normt = (art.get("normalized_title") or "").lower()
        s = 0
        for t in qtokens:
            if t in title:
                s += 2
            if t in normt:
                s += 1
        # small bias to available
        if art.get("status") == "available":
            s += 1
        return s

    candidates = [a for a in articles if a.get("language") == language and isinstance(a.get("normalized_title"), str)]
    scored = [(a, _score(a)) for a in candidates]
    scored = [x for x in scored if x[1] > 0]
    scored.sort(key=lambda x: (-x[1], (x[0].get("normalized_title") or "")))

    results = []
    for a, sc in scored[: int(limit)]:
        results.append({
            "title": a.get("title") or a.get("normalized_title"),
            "normalized_title": a.get("normalized_title"),
            "snippet": (a.get("summary_text")[:200] + "…") if isinstance(a.get("summary_text"), str) and len(a.get("summary_text")) > 200 else a.get("summary_text"),
            "page_id": a.get("page_id"),
        })

    if not results:
        # running->succeeded with 0 results but tool contract says NOT_FOUND only when no matches
        _update_job({"status": "succeeded", "result_count": 0, "results": [], "completed_at": now_iso})
        _log("search_wikipedia", client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000, {"search_query_id": srq["id"], "result_count": 0})
        return _err("NOT_FOUND", "Wikipedia returned no matches for the given query.", query=query, language=language)

    # success
    _update_job({"status": "succeeded", "result_count": len(results), "results": results, "completed_at": now_iso})

    # update key last_used_at on successful authenticated call
    if key:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            krow = next((k for k in keys if k.get("id") == key.get("id")), None)
            if krow:
                krow["last_used_at"] = now_iso
                krow["updated_at"] = now_iso
                try:
                    _save("api_keys.json", keys)
                except Exception:
                    pass

    _log("search_wikipedia", client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000,
         {"search_query_id": srq["id"], "result_count": len(results)})
    return {
        "search_query": srq,
        "results": results,
        "result_count": len(results),
        "language": language,
    }

def get_article(title, **_extra):
    import json, os, datetime, time, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    searches = _load("search_queries.json")
    articles = _load("articles.json")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _normalize_title(s):
        s = s.replace("_", " ")
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _normalized_key(s):
        return _normalize_title(s).lower()

    def _parse_dt(s):
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        if exp is None:
            return False
        return now >= exp

    def _resolve_context():
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            c = next((x for x in active_clients if x.get("id") == k.get("client_id")), None)
            if c:
                return c, k
        return active_clients[0], None

    # Log call in search_queries as a minimal request log row (succeeded/failed).
    # This is a pragmatic adaptation: schema provides no general request log.
    req_row = None
    client, key = _resolve_context()
    try:
        req_row = {
            "id": _new_id("call"),
            "client_id": client.get("id") if client else None,
            "api_key_id": key.get("id") if key else None,
            "language": (client or {}).get("default_language") or "en",
            "query": f"get_article:{title if isinstance(title, str) else ''}",
            "limit": 1,
            "status": "running",
            "result_count": None,
            "results": None,
            "error_message": None,
            "requested_at": now_iso,
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        searches.append(req_row)
        _save("search_queries.json", searches)
    except Exception:
        return _err("CONFLICT", "Failed to record request.")

    def _finalize(status, error_message=None):
        try:
            req_row["status"] = status
            req_row["error_message"] = error_message
            req_row["result_count"] = 1 if status == "succeeded" else 0
            req_row["results"] = []
            req_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            req_row["updated_at"] = req_row["completed_at"]
            _save("search_queries.json", searches)
        except Exception:
            pass

    # Auth
    if client is None or client.get("status") != "active":
        _finalize("failed", "Unauthorized")
        return _err("UNAUTHORIZED", "Not authorized to access the integration.")
    if key is not None and key.get("status") != "active":
        _finalize("failed", "API key revoked")
        return _err("UNAUTHORIZED", "API key is not active.")

    # Validation
    if not isinstance(title, str) or not title.strip():
        _finalize("failed", "Validation error")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")

    # Quota: daily successful calls cannot exceed daily_request_limit
    day = now_iso[:10]
    daily_limit = client.get("daily_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0:
        _finalize("failed", "Client configuration invalid")
        return _err("CONFLICT", "Client configuration invalid.")
    used = sum(
        1 for r in searches
        if r.get("client_id") == client.get("id") and (r.get("requested_at") or "")[:10] == day and r.get("status") == "succeeded"
    )
    if used >= daily_limit:
        _finalize("failed", "Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, used=used)

    # Find or create article row
    lang = client.get("default_language") or "en"
    if not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", lang):
        lang = "en"
    norm_title = _normalized_key(title)
    row = next((a for a in articles if a.get("language") == lang and a.get("normalized_title") == norm_title), None)

    needs_refresh = True
    if row:
        if row.get("status") == "available" and not _is_expired(row) and row.get("full_text"):
            needs_refresh = False
        else:
            # transition to stale if was available but expired
            if row.get("status") == "available" and _is_expired(row):
                row["status"] = "stale"
                row["updated_at"] = now_iso
                try:
                    _save("articles.json", articles)
                except Exception:
                    pass
    else:
        # create placeholder row
        row = {
            "id": _new_id("art"),
            "language": lang,
            "title": _normalize_title(title),
            "normalized_title": norm_title,
            "page_id": None,
            "revision_id": None,
            "status": "stale",
            "full_text": None,
            "summary_text": None,
            "sections": None,
            "links": None,
            "categories": None,
            "fetched_at": None,
            "expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        articles.append(row)
        try:
            _save("articles.json", articles)
        except Exception:
            _finalize("failed", "Failed to persist article placeholder")
            return _err("CONFLICT", "Failed to persist article placeholder.")

    if needs_refresh:
        endpoint = f"https://{lang}.wikipedia.org/w/api.php"
        params = {
            "action": "query",
            "format": "json",
            "prop": "extracts|revisions|links|categories",
            "titles": _normalize_title(title),
            "explaintext": "1",
            "exsectionformat": "plain",
            "redirects": "1",
            "rvprop": "ids",
            "pllimit": "max",
            "cllimit": "max",
        }
        url = endpoint + "?" + urllib.parse.urlencode(params)
        try:
            with urllib.request.urlopen(url, timeout=12) as resp:
                body = resp.read().decode("utf-8")
            data = json.loads(body)
        except Exception as e:
            row["status"] = "error"
            row["error_message"] = f"Wikipedia request failed: {type(e).__name__}"  # non-schema, tolerated
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            _finalize("failed", "Wikipedia request failed")
            return _err("CONFLICT", "Failed to reach Wikipedia or parse response.")

        pages = (((data or {}).get("query") or {}).get("pages") or {})
        page = None
        for _, p in pages.items():
            page = p
            break

        if not page or page.get("missing") is not None:
            row["status"] = "missing"
            row["full_text"] = None
            row["summary_text"] = None
            row["sections"] = None
            row["links"] = None
            row["categories"] = None
            row["page_id"] = None
            row["revision_id"] = None
            row["fetched_at"] = now_iso
            row["expires_at"] = (now + datetime.timedelta(hours=6)).replace(microsecond=0).isoformat() + "Z"
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            _finalize("failed", "Not found")
            return _err("NOT_FOUND", "Wikipedia page not found.")

        extract = page.get("extract")
        if not isinstance(extract, str) or not extract.strip():
            row["status"] = "error"
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            _finalize("failed", "No extract returned")
            return _err("CONFLICT", "Wikipedia returned no extract for this page.")

        # canonical title from Wikipedia response
        canonical_title = page.get("title") if isinstance(page.get("title"), str) else _normalize_title(title)

        # naive summary: first paragraph up to ~500 chars
        paras = [p.strip() for p in extract.split("\n") if p.strip()]
        summary = paras[0] if paras else None
        if summary and len(summary) > 600:
            summary = summary[:597].rsplit(" ", 1)[0] + "..."

        # sections: infer from headings "== X =="
        sections = []
        for line in extract.splitlines():
            m = re.match(r"^(=+)\s*(.*?)\s*\1\s*$", line.strip())
            if m:
                level = max(1, len(m.group(1)) - 1)
                st = m.group(2).strip()
                if st:
                    anchor = re.sub(r"\s+", "_", st.strip())
                    sections.append({"index": len(sections), "title": st, "anchor": anchor, "level": level})

        links = []
        for l in (page.get("links") or []):
            lt = l.get("title")
            if isinstance(lt, str) and lt.strip():
                nlt = _normalized_key(lt)
                links.append({"title": lt, "normalized_title": nlt, "href": None})

        categories = []
        for c in (page.get("categories") or []):
            ct = c.get("title")
            if isinstance(ct, str) and ct.strip():
                categories.append({"title": ct})

        revs = page.get("revisions") or []
        rev_id = None
        if isinstance(revs, list) and revs:
            rid = revs[0].get("revid")
            if isinstance(rid, int) and rid > 0:
                rev_id = rid

        pid = page.get("pageid")
        row["title"] = canonical_title
        row["normalized_title"] = _normalized_key(canonical_title)
        row["page_id"] = pid if isinstance(pid, int) and pid > 0 else None
        row["revision_id"] = rev_id
        row["status"] = "available"
        row["full_text"] = extract
        row["summary_text"] = summary
        row["sections"] = sections if sections else (row.get("sections") or [])
        row["links"] = links if links else (row.get("links") or [])
        row["categories"] = categories if categories else (row.get("categories") or [])
        row["fetched_at"] = now_iso
        row["expires_at"] = (now + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
        row["updated_at"] = now_iso

        # persist
        try:
            _save("articles.json", articles)
        except Exception:
            _finalize("failed", "Failed to persist article")
            return _err("CONFLICT", "Failed to persist article content.")

    # update key usage
    if key is not None:
        try:
            for k in keys:
                if k.get("id") == key.get("id"):
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", keys)
        except Exception:
            pass

    _finalize("succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "article": {
            "id": row.get("id"),
            "language": row.get("language"),
            "title": row.get("title"),
            "page_id": row.get("page_id"),
            "revision_id": row.get("revision_id"),
            "status": row.get("status"),
            "full_text": row.get("full_text"),
            "summary_text": row.get("summary_text"),
            "sections": row.get("sections"),
            "links": row.get("links"),
            "categories": row.get("categories"),
            "fetched_at": row.get("fetched_at"),
            "expires_at": row.get("expires_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        },
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
            "latency_ms": latency_ms,
            "requested_at": req_row["requested_at"],
            "completed_at": req_row["completed_at"],
        },
    }

def get_summary(title, **_extra):
    import json, os, datetime, time, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    searches = _load("search_queries.json")
    articles = _load("articles.json")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _normalize_title(s):
        s = s.replace("_", " ")
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _normalized_key(s):
        return _normalize_title(s).lower()

    def _parse_dt(s):
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        if exp is None:
            return False
        return now >= exp

    def _resolve_context():
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            c = next((x for x in active_clients if x.get("id") == k.get("client_id")), None)
            if c:
                return c, k
        return active_clients[0], None

    client, key = _resolve_context()

    # request log
    req_row = None
    try:
        req_row = {
            "id": _new_id("call"),
            "client_id": client.get("id") if client else None,
            "api_key_id": key.get("id") if key else None,
            "language": (client or {}).get("default_language") or "en",
            "query": f"get_summary:{title if isinstance(title, str) else ''}",
            "limit": 1,
            "status": "running",
            "result_count": None,
            "results": None,
            "error_message": None,
            "requested_at": now_iso,
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        searches.append(req_row)
        _save("search_queries.json", searches)
    except Exception:
        return _err("CONFLICT", "Failed to record request.")

    def _finalize(status, error_message=None):
        try:
            req_row["status"] = status
            req_row["error_message"] = error_message
            req_row["result_count"] = 1 if status == "succeeded" else 0
            req_row["results"] = []
            req_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            req_row["updated_at"] = req_row["completed_at"]
            _save("search_queries.json", searches)
        except Exception:
            pass

    if client is None or client.get("status") != "active":
        _finalize("failed", "Unauthorized")
        return _err("UNAUTHORIZED", "Not authorized to access the integration.")
    if key is not None and key.get("status") != "active":
        _finalize("failed", "API key revoked")
        return _err("UNAUTHORIZED", "API key is not active.")

    if not isinstance(title, str) or not title.strip():
        _finalize("failed", "Validation error")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")

    day = now_iso[:10]
    daily_limit = client.get("daily_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0:
        _finalize("failed", "Client configuration invalid")
        return _err("CONFLICT", "Client configuration invalid.")
    used = sum(
        1 for r in searches
        if r.get("client_id") == client.get("id") and (r.get("requested_at") or "")[:10] == day and r.get("status") == "succeeded"
    )
    if used >= daily_limit:
        _finalize("failed", "Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, used=used)

    lang = client.get("default_language") or "en"
    if not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", lang):
        lang = "en"
    norm_title = _normalized_key(title)
    row = next((a for a in articles if a.get("language") == lang and a.get("normalized_title") == norm_title), None)

    def _refresh():
        nonlocal row
        if row is None:
            row = {
                "id": _new_id("art"),
                "language": lang,
                "title": _normalize_title(title),
                "normalized_title": norm_title,
                "page_id": None,
                "revision_id": None,
                "status": "stale",
                "full_text": None,
                "summary_text": None,
                "sections": None,
                "links": None,
                "categories": None,
                "fetched_at": None,
                "expires_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            articles.append(row)
            try:
                _save("articles.json", articles)
            except Exception:
                return _err("CONFLICT", "Failed to persist article placeholder.")

        endpoint = f"https://{lang}.wikipedia.org/w/api.php"
        params = {
            "action": "query",
            "format": "json",
            "prop": "extracts|revisions",
            "titles": _normalize_title(title),
            "explaintext": "1",
            "exintro": "1",
            "redirects": "1",
            "rvprop": "ids",
        }
        url = endpoint + "?" + urllib.parse.urlencode(params)
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                body = resp.read().decode("utf-8")
            data = json.loads(body)
        except Exception as e:
            row["status"] = "error"
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("CONFLICT", "Failed to reach Wikipedia or parse response.", detail=type(e).__name__)

        pages = (((data or {}).get("query") or {}).get("pages") or {})
        page = None
        for _, p in pages.items():
            page = p
            break

        if not page or page.get("missing") is not None:
            row["status"] = "missing"
            row["summary_text"] = None
            row["fetched_at"] = now_iso
            row["expires_at"] = (now + datetime.timedelta(hours=6)).replace(microsecond=0).isoformat() + "Z"
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("NOT_FOUND", "Wikipedia page not found.")

        extract = page.get("extract")
        if not isinstance(extract, str) or not extract.strip():
            row["status"] = "error"
            row["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("CONFLICT", "Wikipedia returned no summary for this page.")

        canonical_title = page.get("title") if isinstance(page.get("title"), str) else _normalize_title(title)
        revs = page.get("revisions") or []
        rev_id = None
        if isinstance(revs, list) and revs:
            rid = revs[0].get("revid")
            if isinstance(rid, int) and rid > 0:
                rev_id = rid

        if len(extract) > 600:
            extract = extract[:597].rsplit(" ", 1)[0] + "..."

        row["title"] = canonical_title
        row["normalized_title"] = _normalized_key(canonical_title)
        pid = page.get("pageid")
        row["page_id"] = pid if isinstance(pid, int) and pid > 0 else None
        row["revision_id"] = rev_id
        row["status"] = "available"
        row["summary_text"] = extract
        row["fetched_at"] = now_iso
        row["expires_at"] = (now + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
        row["updated_at"] = now_iso
        try:
            _save("articles.json", articles)
        except Exception:
            return _err("CONFLICT", "Failed to persist refreshed summary.")
        return None

    if row and row.get("status") == "available" and not _is_expired(row) and row.get("summary_text"):
        summary = row.get("summary_text")
    else:
        err = _refresh()
        if err:
            _finalize("failed", err["error"]["message"])
            return err
        summary = row.get("summary_text")
        if not summary:
            _finalize("failed", "Not found")
            return _err("NOT_FOUND", "Wikipedia page not found.")

    if key is not None:
        try:
            for k in keys:
                if k.get("id") == key.get("id"):
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", keys)
        except Exception:
            pass

    _finalize("succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "title": row.get("title") if row else _normalize_title(title),
        "language": lang,
        "summary": summary,
        "article_status": row.get("status") if row else None,
        "fetched_at": row.get("fetched_at") if row else None,
        "expires_at": row.get("expires_at") if row else None,
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
            "latency_ms": latency_ms,
            "requested_at": req_row["requested_at"],
            "completed_at": req_row["completed_at"],
        },
    }

def summarize_article_for_query(title, query, max_length=250, **_extra):
    import json, os, datetime, time, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    searches = _load("search_queries.json")
    articles = _load("articles.json")
    artifacts = _load("derived_artifacts.json")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _normalize_title(s):
        s = s.replace("_", " ")
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _normalized_key(s):
        return _normalize_title(s).lower()

    def _parse_dt(s):
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        if exp is None:
            return False
        return now >= exp

    def _resolve_context():
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            c = next((x for x in active_clients if x.get("id") == k.get("client_id")), None)
            if c:
                return c, k
        return active_clients[0], None

    client, key = _resolve_context()

    # request log (search_queries)
    req_row = None
    try:
        req_row = {
            "id": _new_id("call"),
            "client_id": client.get("id") if client else None,
            "api_key_id": key.get("id") if key else None,
            "language": (client or {}).get("default_language") or "en",
            "query": f"summarize_article_for_query:{title if isinstance(title, str) else ''}",
            "limit": 1,
            "status": "running",
            "result_count": None,
            "results": None,
            "error_message": None,
            "requested_at": now_iso,
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        searches.append(req_row)
        _save("search_queries.json", searches)
    except Exception:
        return _err("CONFLICT", "Failed to record request.")

    def _finalize(status, error_message=None):
        try:
            req_row["status"] = status
            req_row["error_message"] = error_message
            req_row["result_count"] = 1 if status == "succeeded" else 0
            req_row["results"] = []
            req_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            req_row["updated_at"] = req_row["completed_at"]
            _save("search_queries.json", searches)
        except Exception:
            pass

    # Auth
    if client is None or client.get("status") != "active":
        _finalize("failed", "Unauthorized")
        return _err("UNAUTHORIZED", "Not authorized to access the integration.")
    if key is not None and key.get("status") != "active":
        _finalize("failed", "API key revoked")
        return _err("UNAUTHORIZED", "API key is not active.")

    # Validation
    if not isinstance(title, str) or not title.strip():
        _finalize("failed", "Validation error")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if not isinstance(query, str) or not query.strip():
        _finalize("failed", "Validation error")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if max_length is not None:
        if not isinstance(max_length, int) or max_length <= 0:
            _finalize("failed", "Validation error")
            return _err("VALIDATION_ERROR", "max_length must be a positive integer when set.")
        if max_length < 50 or max_length > 2000:
            _finalize("failed", "Validation error")
            return _err("VALIDATION_ERROR", "max_length must be between 50 and 2000.")

    # Quota
    day = now_iso[:10]
    daily_limit = client.get("daily_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0:
        _finalize("failed", "Client configuration invalid")
        return _err("CONFLICT", "Client configuration invalid.")
    used = sum(
        1 for r in searches
        if r.get("client_id") == client.get("id") and (r.get("requested_at") or "")[:10] == day and r.get("status") == "succeeded"
    )
    if used >= daily_limit:
        _finalize("failed", "Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, used=used)

    # Ensure article is available (refresh if needed)
    lang = client.get("default_language") or "en"
    if not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", lang):
        lang = "en"
    norm_title = _normalized_key(title)
    article = next((a for a in articles if a.get("language") == lang and a.get("normalized_title") == norm_title), None)

    def _refresh_article():
        nonlocal article
        if article is None:
            article = {
                "id": _new_id("art"),
                "language": lang,
                "title": _normalize_title(title),
                "normalized_title": norm_title,
                "page_id": None,
                "revision_id": None,
                "status": "stale",
                "full_text": None,
                "summary_text": None,
                "sections": None,
                "links": None,
                "categories": None,
                "fetched_at": None,
                "expires_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            articles.append(article)
            try:
                _save("articles.json", articles)
            except Exception:
                return _err("CONFLICT", "Failed to persist article placeholder.")

        endpoint = f"https://{lang}.wikipedia.org/w/api.php"
        params = {
            "action": "query",
            "format": "json",
            "prop": "extracts|revisions",
            "titles": _normalize_title(title),
            "explaintext": "1",
            "redirects": "1",
            "rvprop": "ids",
        }
        url = endpoint + "?" + urllib.parse.urlencode(params)
        try:
            with urllib.request.urlopen(url, timeout=12) as resp:
                body = resp.read().decode("utf-8")
            data = json.loads(body)
        except Exception as e:
            article["status"] = "error"
            article["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("CONFLICT", "Failed to reach Wikipedia or parse response.", detail=type(e).__name__)

        pages = (((data or {}).get("query") or {}).get("pages") or {})
        page = None
        for _, p in pages.items():
            page = p
            break

        if not page or page.get("missing") is not None:
            article["status"] = "missing"
            article["full_text"] = None
            article["summary_text"] = None
            article["fetched_at"] = now_iso
            article["expires_at"] = (now + datetime.timedelta(hours=6)).replace(microsecond=0).isoformat() + "Z"
            article["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("NOT_FOUND", "Wikipedia page not found.")

        extract = page.get("extract")
        if not isinstance(extract, str) or not extract.strip():
            article["status"] = "error"
            article["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
            return _err("CONFLICT", "Wikipedia returned no content for this page.")

        canonical_title = page.get("title") if isinstance(page.get("title"), str) else _normalize_title(title)
        pid = page.get("pageid")
        revs = page.get("revisions") or []
        rev_id = None
        if isinstance(revs, list) and revs:
            rid = revs[0].get("revid")
            if isinstance(rid, int) and rid > 0:
                rev_id = rid

        # summary first paragraph
        paras = [p.strip() for p in extract.split("\n") if p.strip()]
        summary = paras[0] if paras else None
        if summary and len(summary) > 600:
            summary = summary[:597].rsplit(" ", 1)[0] + "..."

        article["title"] = canonical_title
        article["normalized_title"] = _normalized_key(canonical_title)
        article["page_id"] = pid if isinstance(pid, int) and pid > 0 else None
        article["revision_id"] = rev_id
        article["status"] = "available"
        article["full_text"] = extract
        article["summary_text"] = summary
        article["fetched_at"] = now_iso
        article["expires_at"] = (now + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
        article["updated_at"] = now_iso
        try:
            _save("articles.json", articles)
        except Exception:
            return _err("CONFLICT", "Failed to persist refreshed article.")
        return None

    if not article or article.get("status") != "available" or _is_expired(article) or not article.get("full_text"):
        if article and article.get("status") == "available" and _is_expired(article):
            article["status"] = "stale"
            article["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
        err = _refresh_article()
        if err:
            _finalize("failed", err["error"]["message"])
            return err

    if article.get("status") != "available":
        _finalize("failed", "Not found")
        return _err("NOT_FOUND", "Wikipedia page not found.")

    # Derived artifact: create or reuse unique key
    # unique(client_id, article_id, artifact_type, coalesce(query,''), coalesce(section_title,''), coalesce(topic_within_article,''), coalesce(max_length,0), coalesce(count,0))
    cid = client.get("id")
    aid = article.get("id")
    qv = query.strip()
    ml = max_length if max_length is not None else 250

    def _find_artifact():
        for a in artifacts:
            if a.get("client_id") != cid:
                continue
            if a.get("article_id") != aid:
                continue
            if a.get("artifact_type") != "query_summary":
                continue
            if (a.get("query") or "") != qv:
                continue
            if (a.get("max_length") or 0) != (ml or 0):
                continue
            if (a.get("section_title") or "") != "":
                continue
            if (a.get("topic_within_article") or "") != "":
                continue
            if (a.get("count") or 0) != 0:
                continue
            return a
        return None

    artifact = _find_artifact()
    if artifact and artifact.get("status") == "available" and not _is_expired(artifact) and isinstance(artifact.get("output_text"), str):
        # serve cache
        pass
    else:
        # create if missing
        if artifact is None:
            artifact = {
                "id": _new_id("dar"),
                "client_id": cid,
                "article_id": aid,
                "artifact_type": "query_summary",
                "query": qv,
                "section_title": None,
                "topic_within_article": None,
                "max_length": ml,
                "count": None,
                "status": "computing",
                "output_text": None,
                "output_items": None,
                "computed_at": None,
                "expires_at": None,
                "error_message": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            artifacts.append(artifact)
        else:
            # transition to computing if stale/expired
            if artifact.get("status") in ("available", "stale", "error"):
                artifact["status"] = "computing"
                artifact["updated_at"] = now_iso

        try:
            _save("derived_artifacts.json", artifacts)
        except Exception:
            _finalize("failed", "Failed to persist artifact computing state")
            return _err("CONFLICT", "Failed to persist artifact state.")

        # "Generate" summary locally (offline heuristic): use article summary + extract sentences containing query terms.
        text = article.get("full_text") or ""
        base = article.get("summary_text") or ""
        terms = [t.lower() for t in re.findall(r"[A-Za-z0-9]+", qv) if len(t) >= 3]
        sentences = re.split(r"(?<=[.!?])\s+", text.replace("\n", " ").strip())
        scored = []
        for s in sentences:
            sl = s.lower()
            score = 0
            for t in terms:
                if t in sl:
                    score += 1
            if score > 0 and len(s.strip()) >= 40:
                scored.append((score, s.strip()))
        scored.sort(key=lambda x: (-x[0], len(x[1])))
        picked = [s for _, s in scored[:5]]

        out = ""
        if base:
            out = base.strip()
        if picked:
            extras = " ".join(picked)
            if out and extras and extras not in out:
                out = (out + "\n\n" + extras).strip()
            elif not out:
                out = extras.strip()
        if not out:
            out = (text[:ml] if isinstance(ml, int) else text[:250]).strip()

        # enforce max length approximately
        if isinstance(ml, int) and ml > 0 and len(out) > ml:
            out = out[:ml].rsplit(" ", 1)[0].strip()
            if out and not out.endswith("."):
                out += "..."

        artifact["status"] = "available"
        artifact["output_text"] = out
        artifact["output_items"] = None
        artifact["computed_at"] = now_iso
        artifact["expires_at"] = (now + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
        artifact["error_message"] = None
        artifact["updated_at"] = now_iso

        try:
            _save("derived_artifacts.json", artifacts)
        except Exception:
            _finalize("failed", "Failed to persist artifact output")
            return _err("CONFLICT", "Failed to persist artifact output.")

    # update key usage
    if key is not None:
        try:
            for k in keys:
                if k.get("id") == key.get("id"):
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", keys)
        except Exception:
            pass

    _finalize("succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "artifact": {
            "id": artifact.get("id"),
            "client_id": artifact.get("client_id"),
            "article_id": artifact.get("article_id"),
            "artifact_type": artifact.get("artifact_type"),
            "query": artifact.get("query"),
            "max_length": artifact.get("max_length"),
            "status": artifact.get("status"),
            "output_text": artifact.get("output_text"),
            "computed_at": artifact.get("computed_at"),
            "expires_at": artifact.get("expires_at"),
            "created_at": artifact.get("created_at"),
            "updated_at": artifact.get("updated_at"),
        },
        "article": {
            "id": article.get("id"),
            "language": article.get("language"),
            "title": article.get("title"),
            "page_id": article.get("page_id"),
            "revision_id": article.get("revision_id"),
            "status": article.get("status"),
            "fetched_at": article.get("fetched_at"),
            "expires_at": article.get("expires_at"),
        },
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
            "latency_ms": latency_ms,
            "requested_at": req_row["requested_at"],
            "completed_at": req_row["completed_at"],
        },
    }

def summarize_article_section(title, section_title, max_length=150, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    endpoint = "summarize_article_section"

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, client_id, api_key_id, status, latency_ms, meta=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(6)}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": now_iso,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_title(s):
        s = s.strip().replace("_", " ")
        s = re.sub(r"\s+", " ", s)
        return s.lower()

    def _pick_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            c = next((x for x in active_clients if x.get("id") == cid), None)
            if c:
                return c, k
        return active_clients[0], None

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _enforce_quota(client_row):
        limit_daily = client_row.get("daily_request_limit")
        if not isinstance(limit_daily, int) or limit_daily < 0:
            return _err("UNAUTHORIZED", "Client is not configured with a valid daily_request_limit.")
        day = _utc_day(now)
        total_success = 0
        logs = _load("request_logs.json")
        if isinstance(logs, list) and logs:
            for r in logs:
                if r.get("client_id") != client_row.get("id"):
                    continue
                ts = _parse_dt(r.get("ts"))
                if not ts or _utc_day(ts) != day:
                    continue
                if r.get("status") == "succeeded":
                    total_success += 1
        if total_success >= limit_daily:
            return _err("QUOTA_EXCEEDED", f"Rate limited: daily quota exceeded for client_id {client_row.get('id')}.",
                        client_id=client_row.get("id"), daily_request_limit=limit_daily, day=day, successful_calls=total_success)
        return None

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        return bool(exp and exp <= now)

    # validate inputs
    if not isinstance(title, str) or not title.strip():
        e = _err("VALIDATION_ERROR", "title must be a non-empty string.")
        _log(endpoint, None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e
    if not isinstance(section_title, str) or not section_title.strip():
        e = _err("VALIDATION_ERROR", "section_title must be a non-empty string.")
        _log(endpoint, None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e
    if max_length is not None:
        if not isinstance(max_length, int) or max_length <= 0:
            e = _err("VALIDATION_ERROR", "max_length must be a positive integer when set.")
            _log(endpoint, None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
            return e
        if max_length < 50 or max_length > 2000:
            e = _err("VALIDATION_ERROR", "max_length must be between 50 and 2000.")
            _log(endpoint, None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
            return e

    client, key = _pick_context()
    if not client:
        e = _err("UNAUTHORIZED", "No active API client is available for this request.")
        _log(endpoint, None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    qerr = _enforce_quota(client)
    if qerr:
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": qerr["error"]})
        return qerr

    # resolve article by (language, normalized_title)
    lang = client.get("default_language") if isinstance(client.get("default_language"), str) and client.get("default_language") else "en"
    ntitle = _normalize_title(title)

    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []

    article = next((a for a in articles if a.get("language") == lang and a.get("normalized_title") == ntitle), None)
    if not article:
        e = _err("NOT_FOUND", "The article does not exist in cache.", title=title, language=lang)
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # ensure sections exist and match
    sections = article.get("sections") if isinstance(article.get("sections"), list) else None
    if not sections or _is_expired(article) or article.get("status") in ("stale", "error", "missing"):
        # attempt lightweight offline refresh: if sections present keep; else cannot fabricate => NOT_FOUND for section match will follow
        # transition article to stale if expired
        if _is_expired(article) and article.get("status") == "available":
            article["status"] = "stale"
            article["updated_at"] = now_iso
            try:
                _save("articles.json", articles)
            except Exception:
                pass
        sections = article.get("sections") if isinstance(article.get("sections"), list) else None

    if not sections:
        e = _err("NOT_FOUND", "Section list is not available for this article.", title=article.get("title") or title)
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # match section title (case-insensitive exact match)
    st_norm = re.sub(r"\s+", " ", section_title.strip()).lower()
    sec = next((s for s in sections if isinstance(s, dict) and isinstance(s.get("title"), str) and re.sub(r"\s+", " ", s["title"].strip()).lower() == st_norm), None)
    if not sec:
        e = _err("NOT_FOUND", "section_title does not match a section in the page.", section_title=section_title, title=article.get("title") or title)
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # derived_artifacts cache key: (client_id, article_id, artifact_type, section_title, max_length)
    artifacts = _load("derived_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    def _coalesce(v, d=""):
        return d if v is None else v

    def _find_artifact():
        for a in artifacts:
            if a.get("client_id") != client.get("id"):
                continue
            if a.get("article_id") != article.get("id"):
                continue
            if a.get("artifact_type") != "section_summary":
                continue
            if _coalesce(a.get("section_title"), "") != section_title:
                continue
            if _coalesce(a.get("max_length"), 0) != (_coalesce(max_length, 0)):
                continue
            # ensure other key parts are empty per unique constraint
            if _coalesce(a.get("query"), "") != "":
                continue
            if _coalesce(a.get("topic_within_article"), "") != "":
                continue
            if _coalesce(a.get("count"), 0) != 0:
                continue
            return a
        return None

    def _artifact_expired(a):
        exp = _parse_dt(a.get("expires_at"))
        return bool(exp and exp <= now)

    existing = _find_artifact()
    if existing and existing.get("status") == "available" and existing.get("output_text") and not _artifact_expired(existing):
        _log(endpoint, client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000,
             {"derived_artifact_id": existing.get("id"), "cache_hit": True})
        return {"derived_artifact": existing, "cache_hit": True}

    # create or reuse artifact row; transition to computing
    def _gen_id():
        return f"wiki_drv_{secrets.token_hex(12)}"

    if not existing:
        existing = {
            "id": _gen_id(),
            "client_id": client.get("id"),
            "article_id": article.get("id"),
            "artifact_type": "section_summary",
            "query": None,
            "section_title": section_title,
            "topic_within_article": None,
            "max_length": max_length,
            "count": None,
            "status": "computing",
            "output_text": None,
            "output_items": None,
            "computed_at": None,
            "expires_at": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        artifacts.append(existing)
    else:
        # legal transitions: stale/error -> computing
        if existing.get("status") in ("available", "stale", "error"):
            existing["status"] = "computing"
        elif existing.get("status") != "computing":
            e = _err("INVALID_TRANSITION", f"Illegal artifact status transition to computing from {existing.get('status')}.",
                     from_status=existing.get("status"), to_status="computing")
            _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
            return e
        existing["updated_at"] = now_iso
        existing["error_message"] = None

    try:
        _save("derived_artifacts.json", artifacts)
    except Exception:
        e = _err("CONFLICT", "Failed to persist derived artifact job.")
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # generate offline summary from available cached text; accept request if article isn't "available" as long as we have some text
    source = None
    if isinstance(article.get("full_text"), str) and article.get("full_text").strip():
        source = article.get("full_text").strip()
    elif isinstance(article.get("summary_text"), str) and article.get("summary_text").strip():
        source = article.get("summary_text").strip()

    if not source:
        # Mark artifact error; this is not a "CONFLICT", it's a real inability to produce output from cached content
        existing["status"] = "error"
        existing["error_message"] = "Cannot compute section summary: article content is not available in cache."
        existing["updated_at"] = now_iso
        try:
            _save("derived_artifacts.json", artifacts)
        except Exception:
            pass
        e = _err("CONFLICT", "Cannot compute section summary because article content is not available in cache.",
                 rule="summarize_article_section requires cached article text (full_text or summary_text).")
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # naive section extraction: if we can find section heading in full_text, summarize nearby; else summarize whole source
    def _make_summary(text, max_len):
        text = re.sub(r"\s+", " ", text).strip()
        if max_len is None:
            max_len = 150
        if len(text) <= max_len:
            return text
        cut = text[:max_len]
        # try to cut at sentence boundary
        m = re.search(r"^(.{50," + str(max_len) + r"}?[.!?])\s", text)
        if m:
            return m.group(1).strip()
        return cut.rstrip() + "…"

    # attempt to focus on section using simple markers
    focused = source
    if isinstance(article.get("full_text"), str):
        ft = article.get("full_text")
        # match markdown-like headings or plain heading lines
        pat = re.compile(r"(^|\n)\s*(#+\s*)?" + re.escape(section_title.strip()) + r"\s*(\n|$)", re.IGNORECASE)
        m = pat.search(ft)
        if m:
            start = m.end()
            focused = ft[start:start + 5000]  # take chunk after heading

    out = _make_summary(focused, max_length)

    # computing -> available
    existing["status"] = "available"
    existing["output_text"] = out
    existing["output_items"] = None
    existing["computed_at"] = now_iso
    existing["expires_at"] = (now + datetime.timedelta(hours=24)).isoformat().replace("+00:00", "Z")
    existing["updated_at"] = now_iso
    existing["error_message"] = None

    try:
        _save("derived_artifacts.json", artifacts)
    except Exception:
        e = _err("CONFLICT", "Failed to persist computed section summary.")
        _log(endpoint, client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    _log(endpoint, client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000,
         {"derived_artifact_id": existing.get("id"), "cache_hit": False, "status": "available"})
    return {"derived_artifact": existing, "cache_hit": False}

def extract_key_facts(title, topic_within_article=None, count=5, **_extra):
    import json, os, datetime, re, time, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_title(s):
        s = s.strip().replace("_", " ")
        s = re.sub(r"\s+", " ", s)
        return s.lower()

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    # auth/quota
    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    client = None
    key = None
    for c in api_clients:
        if c.get("status") == "active" and isinstance(c.get("daily_request_limit"), int) and c.get("daily_request_limit") >= 0:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active API client is available for this request.")
    for k in api_keys:
        if k.get("status") == "active" and k.get("client_id") == client.get("id"):
            key = k
            break

    derived = _load("derived_artifacts.json")
    def _utc_day_prefix(dt): return dt.strftime("%Y-%m-%d")
    today = _utc_day_prefix(now)
    used = 0
    for a in derived:
        if a.get("client_id") != client.get("id"):
            continue
        if a.get("status") != "available":
            continue
        ua = _parse_dt(a.get("updated_at"))
        if ua and _utc_day_prefix(ua) == today:
            used += 1
    if used >= client.get("daily_request_limit", 0):
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded for this API client.", limit=client.get("daily_request_limit"), used=used)

    # validate
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if not isinstance(count, int) or count <= 0:
        return _err("VALIDATION_ERROR", "count must be a positive integer.")
    if count < 1 or count > 50:
        return _err("VALIDATION_ERROR", "count must be between 1 and 50.", min=1, max=50)
    if topic_within_article is not None and (not isinstance(topic_within_article, str) or not topic_within_article.strip()):
        return _err("VALIDATION_ERROR", "topic_within_article must be a non-empty string when provided.")
    topic = topic_within_article.strip() if isinstance(topic_within_article, str) else None

    language = client.get("default_language") or "en"
    if not isinstance(language, str) or not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", language):
        language = "en"
    norm_title = _normalize_title(title)

    # articles resolve/refresh (minimal using summary + parse for links/categories if needed)
    articles = _load("articles.json")

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        return bool(exp and now >= exp)

    def _refresh_article(existing_row):
        nonlocal articles
        api_base = f"https://{language}.wikipedia.org"
        disp_title = existing_row.get("title") if existing_row else title.strip()
        missing = False
        error_message = None
        canonical_title = None
        summary_text = None
        page_id = None
        revision_id = None
        links = None
        categories = None
        full_text = None
        sections = None

        try:
            summ_url = f"{api_base}/api/rest_v1/page/summary/{urllib.parse.quote(disp_title, safe='')}"
            req = urllib.request.Request(summ_url, headers={"User-Agent": "offline-integration-server/1.0"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            if data.get("type") in ("https://mediawiki.org/wiki/HyperSwitch/errors/not_found", "not_found"):
                missing = True
            else:
                canonical_title = data.get("title") or disp_title
                summary_text = data.get("extract")
                page_id = data.get("pageid")
                revision_id = data.get("revision")
        except Exception as e:
            error_message = f"Failed to fetch summary: {e.__class__.__name__}"

        if not missing and error_message is None:
            try:
                params = {
                    "action": "parse",
                    "page": canonical_title or disp_title,
                    "prop": "links|categories|wikitext|sections",
                    "format": "json",
                    "redirects": "1",
                }
                url = api_base + "/w/api.php?" + urllib.parse.urlencode(params)
                req = urllib.request.Request(url, headers={"User-Agent": "offline-integration-server/1.0"})
                with urllib.request.urlopen(req, timeout=10) as resp:
                    pdata = json.loads(resp.read().decode("utf-8"))
                if "error" in pdata:
                    info = (pdata.get("error") or {}).get("info") or ""
                    code = (pdata.get("error") or {}).get("code") or ""
                    if "missing" in info.lower() or code in ("missingtitle", "invalidtitle"):
                        missing = True
                    else:
                        error_message = "Failed to parse page."
                else:
                    parse = pdata.get("parse") or {}
                    sec_list = parse.get("sections") or []
                    sections = []
                    for s in sec_list:
                        sections.append({
                            "index": int(s.get("index")) if str(s.get("index", "")).isdigit() else None,
                            "title": s.get("line") or "",
                            "anchor": s.get("anchor") or "",
                            "level": int(s.get("level")) if str(s.get("level", "")).isdigit() else None
                        })
                    l_list = parse.get("links") or []
                    links = []
                    for l in l_list:
                        lt = l.get("*") or l.get("title") or ""
                        if lt:
                            links.append({"title": lt, "normalized_title": _normalize_title(lt), "href": None})
                    c_list = parse.get("categories") or []
                    categories = []
                    for c in c_list:
                        ct = c.get("*") or c.get("title") or ""
                        if ct:
                            categories.append({"title": ct})
                    wt = (parse.get("wikitext") or {}).get("*")
                    full_text = wt if isinstance(wt, str) else None
            except Exception as e:
                error_message = f"Failed to fetch structure: {e.__class__.__name__}"

        ttl = 24
        fetched_at = now_iso if (not missing and error_message is None) else None
        expires_at = (now + datetime.timedelta(hours=ttl)).isoformat() + "Z" if fetched_at else None

        if existing_row is None:
            row = {
                "id": _gen_id("art"),
                "language": language,
                "title": canonical_title or title.strip(),
                "normalized_title": norm_title,
                "page_id": page_id if isinstance(page_id, int) else None,
                "revision_id": revision_id if isinstance(revision_id, int) else None,
                "status": "missing" if missing else ("error" if error_message else "available"),
                "full_text": full_text,
                "summary_text": summary_text,
                "sections": sections,
                "links": links,
                "categories": categories,
                "fetched_at": fetched_at,
                "expires_at": expires_at,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            articles.append(row)
            _save("articles.json", articles)
            return row

        existing_row["title"] = canonical_title or existing_row.get("title") or title.strip()
        existing_row["page_id"] = page_id if isinstance(page_id, int) else existing_row.get("page_id")
        existing_row["revision_id"] = revision_id if isinstance(revision_id, int) else existing_row.get("revision_id")
        if missing:
            existing_row["status"] = "missing"
            existing_row["summary_text"] = None
            existing_row["full_text"] = None
            existing_row["sections"] = None
            existing_row["links"] = None
            existing_row["categories"] = None
            existing_row["fetched_at"] = None
            existing_row["expires_at"] = None
        elif error_message:
            existing_row["status"] = "error"
        else:
            existing_row["status"] = "available"
            existing_row["summary_text"] = summary_text
            existing_row["full_text"] = full_text
            existing_row["sections"] = sections
            existing_row["links"] = links
            existing_row["categories"] = categories
            existing_row["fetched_at"] = fetched_at
            existing_row["expires_at"] = expires_at
        existing_row["updated_at"] = now_iso
        _save("articles.json", articles)
        return existing_row

    article = None
    for r in articles:
        if r.get("language") == language and r.get("normalized_title") == norm_title:
            article = r
            break
    if article is None or article.get("status") in ("stale", "missing", "error") or _is_expired(article):
        article = _refresh_article(article)

    if article.get("status") == "missing":
        return _err("NOT_FOUND", "Article not found on Wikipedia.", title=title, language=language)
    if article.get("status") != "available":
        return _err("CONFLICT", "Article is not available for fact extraction.", status=article.get("status"))

    # If topic provided, ensure it's locatable in article text/summary/sections titles.
    haystacks = []
    if isinstance(article.get("summary_text"), str):
        haystacks.append(article["summary_text"])
    if isinstance(article.get("full_text"), str):
        haystacks.append(article["full_text"])
    if isinstance(article.get("sections"), list):
        haystacks.append(" ".join([(s.get("title") or "") for s in article["sections"] if isinstance(s, dict)]))
    if topic:
        found = any(topic.casefold() in (h or "").casefold() for h in haystacks)
        if not found:
            return _err("NOT_FOUND", "topic_within_article could not be located within the article content.", topic_within_article=topic)

    # derived artifact reuse
    def _parse_exp(s):
        exp = _parse_dt(s)
        return bool(exp and now >= exp)

    artifact = None
    for a in derived:
        if a.get("client_id") != client.get("id"):
            continue
        if a.get("article_id") != article.get("id"):
            continue
        if a.get("artifact_type") != "key_facts":
            continue
        if (a.get("topic_within_article") or "") != (topic or ""):
            continue
        if (a.get("count") or None) != count:
            continue
        artifact = a
        break

    if artifact and artifact.get("status") == "available" and not _parse_exp(artifact.get("expires_at")) and isinstance(artifact.get("output_items"), list):
        if key is not None:
            key["last_used_at"] = now_iso
            key["updated_at"] = now_iso
            _save("api_keys.json", api_keys)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "artifact": artifact,
            "article": {"id": article.get("id"), "title": article.get("title"), "language": article.get("language")},
            "cached": True,
            "latency_ms": latency_ms
        }

    if artifact is None:
        artifact = {
            "id": _gen_id("da"),
            "client_id": client.get("id"),
            "article_id": article.get("id"),
            "artifact_type": "key_facts",
            "query": None,
            "section_title": None,
            "topic_within_article": topic,
            "max_length": None,
            "count": count,
            "status": "computing",
            "output_text": None,
            "output_items": None,
            "computed_at": None,
            "expires_at": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        derived.append(artifact)
    else:
        artifact["status"] = "computing"
        artifact["updated_at"] = now_iso
        artifact["error_message"] = None

    _save("derived_artifacts.json", derived)

    # Compute key facts: naive extractive bullets from summary + first lines of wikitext.
    try:
        text = (article.get("summary_text") or "") + "\n" + (article.get("full_text") or "")
        text = re.sub(r"\{\{.*?\}\}", " ", text, flags=re.S)  # drop templates crudely
        text = re.sub(r"\[\[([^\|\]]+)\|([^\]]+)\]\]", r"\2", text)  # wiki links
        text = re.sub(r"\[\[([^\]]+)\]\]", r"\1", text)
        text = re.sub(r"''+", "", text)
        text = re.sub(r"\s+", " ", text).strip()

        if topic:
            # focus by selecting sentences containing topic first
            sents = re.split(r"(?<=[\.\!\?])\s+", text)
            primary = [s for s in sents if topic.casefold() in s.casefold()]
            secondary = [s for s in sents if s not in primary]
            sents = primary + secondary
        else:
            sents = re.split(r"(?<=[\.\!\?])\s+", text)

        items = []
        for s in sents:
            s = (s or "").strip()
            if not s:
                continue
            # skip very short
            if len(s) < 30:
                continue
            items.append({"fact": s, "confidence": None, "source_hint": "wikipedia"})
            if len(items) >= count:
                break

        if not items:
            artifact["status"] = "error"
            artifact["error_message"] = "Insufficient content to extract facts."
        else:
            artifact["output_items"] = items[:count]
            artifact["status"] = "available"
            artifact["computed_at"] = now_iso
            artifact["expires_at"] = (now + datetime.timedelta(hours=24)).isoformat() + "Z"
            artifact["error_message"] = None
    except Exception as e:
        artifact["status"] = "error"
        artifact["error_message"] = f"Computation failed: {e.__class__.__name__}"

    artifact["updated_at"] = now_iso
    _save("derived_artifacts.json", derived)

    if artifact.get("status") != "available":
        return _err("CONFLICT", "Failed to extract key facts.", status=artifact.get("status"), error_message=artifact.get("error_message"))

    if key is not None:
        key["last_used_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "artifact": artifact,
        "article": {"id": article.get("id"), "title": article.get("title"), "language": article.get("language")},
        "cached": False,
        "latency_ms": latency_ms
    }

