    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_title(s):
        s = s.strip().replace("_", " ")
        s = re.sub(r"\s+", " ", s)
        return s.lower()

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    # auth/quota
    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    client = None
    key = None
    for c in api_clients:
        if c.get("status") == "active" and isinstance(c.get("daily_request_limit"), int) and c.get("daily_request_limit") >= 0:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active API client is available for this request.")
    for k in api_keys:
        if k.get("status") == "active" and k.get("client_id") == client.get("id"):
            key = k
            break

    derived = _load("derived_artifacts.json")
    def _utc_day_prefix(dt): return dt.strftime("%Y-%m-%d")
    today = _utc_day_prefix(now)
    used = 0
    for a in derived:
        if a.get("client_id") != client.get("id"):
            continue
        if a.get("status") != "available":
            continue
        ua = _parse_dt(a.get("updated_at"))
        if ua and _utc_day_prefix(ua) == today:
            used += 1
    if used >= client.get("daily_request_limit", 0):
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded for this API client.", limit=client.get("daily_request_limit"), used=used)

    # validate
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if not isinstance(limit, int) or limit <= 0:
        return _err("VALIDATION_ERROR", "limit must be a positive integer.")
    if limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 50.", min=1, max=50)

    language = client.get("default_language") or "en"
    if not isinstance(language, str) or not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", language):
        language = "en"
    norm_title = _normalize_title(title)

    articles = _load("articles.json")
    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        return bool(exp and now >= exp)

    def _refresh_article(existing_row):
        nonlocal articles
        api_base = f"https://{language}.wikipedia.org"
        disp_title = existing_row.get("title") if existing_row else title.strip()
        missing = False
        error_message = None
        canonical_title = None
        summary_text = None
        page_id = None
        revision_id = None
        links = None
        categories = None
        sections = None
        full_text = None

        try:
            summ_url = f"{api_base}/api/rest_v1/page/summary/{urllib.parse.quote(disp_title, safe='')}"
            req = urllib.request.Request(summ_url, headers={"User-Agent": "offline-integration-server/1.0"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            if data.get("type") in ("https://mediawiki.org/wiki/HyperSwitch/errors/not_found", "not_found"):
                missing = True
            else:
                canonical_title = data.get("title") or disp_title
                summary_text = data.get("extract")
                page_id = data.get("pageid")
                revision_id = data.get("revision")
        except Exception as e:
            error_message = f"Failed to fetch summary: {e.__class__.__name__}"

        if not missing and error_message is None:
            try:
                params = {
                    "action": "parse",
                    "page": canonical_title or disp_title,
                    "prop": "links|categories|sections",
                    "format": "json",
                    "redirects": "1",
                }
                url = api_base + "/w/api.php?" + urllib.parse.urlencode(params)
                req = urllib.request.Request(url, headers={"User-Agent": "offline-integration-server/1.0"})
                with urllib.request.urlopen(req, timeout=10) as resp:
                    pdata = json.loads(resp.read().decode("utf-8"))
                if "error" in pdata:
                    info = (pdata.get("error") or {}).get("info") or ""
                    code = (pdata.get("error") or {}).get("code") or ""
                    if "missing" in info.lower() or code in ("missingtitle", "invalidtitle"):
                        missing = True
                    else:
                        error_message = "Failed to parse page."
                else:
                    parse = pdata.get("parse") or {}
                    sec_list = parse.get("sections") or []
                    sections = []
                    for s in sec_list:
                        sections.append({
                            "index": int(s.get("index")) if str(s.get("index", "")).isdigit() else None,
                            "title": s.get("line") or "",
                            "anchor": s.get("anchor") or "",
                            "level": int(s.get("level")) if str(s.get("level", "")).isdigit() else None
                        })
                    l_list = parse.get("links") or []
                    links = []
                    for l in l_list:
                        lt = l.get("*") or l.get("title") or ""
                        if lt:
                            links.append({"title": lt, "normalized_title": _normalize_title(lt), "href": None})
                    c_list = parse.get("categories") or []
                    categories = []
                    for c in c_list:
                        ct = c.get("*") or c.get("title") or ""
                        if ct:
                            categories.append({"title": ct})
            except Exception as e:
                error_message = f"Failed to fetch structure: {e.__class__.__name__}"

        fetched_at = now_iso if (not missing and error_message is None) else None
        expires_at = (now + datetime.timedelta(hours=24)).isoformat() + "Z" if fetched_at else None

        if existing_row is None:
            row = {
                "id": _gen_id("art"),
                "language": language,
                "title": canonical_title or title.strip(),
                "normalized_title": norm_title,
                "page_id": page_id if isinstance(page_id, int) else None,
                "revision_id": revision_id if isinstance(revision_id, int) else None,
                "status": "missing" if missing else ("error" if error_message else "available"),
                "full_text": full_text,
                "summary_text": summary_text,
                "sections": sections,
                "links": links,
                "categories": categories,
                "fetched_at": fetched_at,
                "expires_at": expires_at,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            articles.append(row)
            _save("articles.json", articles)
            return row

        existing_row["title"] = canonical_title or existing_row.get("title") or title.strip()
        existing_row["page_id"] = page_id if isinstance(page_id, int) else existing_row.get("page_id")
        existing_row["revision_id"] = revision_id if isinstance(revision_id, int) else existing_row.get("revision_id")
        if missing:
            existing_row["status"] = "missing"
            existing_row["summary_text"] = None
            existing_row["sections"] = None
            existing_row["links"] = None
            existing_row["categories"] = None
            existing_row["fetched_at"] = None
            existing_row["expires_at"] = None
        elif error_message:
            existing_row["status"] = "error"
        else:
            existing_row["status"] = "available"
            existing_row["summary_text"] = summary_text
            existing_row["sections"] = sections
            existing_row["links"] = links
            existing_row["categories"] = categories
            existing_row["fetched_at"] = fetched_at
            existing_row["expires_at"] = expires_at
        existing_row["updated_at"] = now_iso
        _save("articles.json", articles)
        return existing_row

    article = None
    for r in articles:
        if r.get("language") == language and r.get("normalized_title") == norm_title:
            article = r
            break
    if article is None or article.get("status") in ("stale", "missing", "error") or _is_expired(article) or article.get("links") is None or article.get("categories") is None:
        article = _refresh_article(article)

    if article.get("status") == "missing":
        return _err("NOT_FOUND", "Article not found on Wikipedia.", title=title, language=language)
    if article.get("status") != "available":
        return _err("CONFLICT", "Article is not available for related topics derivation.", status=article.get("status"))

    # derived artifact cache for related_topics with count=limit
    derived = _load("derived_artifacts.json")

    def _artifact_expired(a):
        exp = _parse_dt(a.get("expires_at"))
        return bool(exp and now >= exp)

    artifact = None
    for a in derived:
        if a.get("client_id") == client.get("id") and a.get("article_id") == article.get("id") and a.get("artifact_type") == "related_topics" and (a.get("count") or None) == limit:
            artifact = a
            break

    if artifact and artifact.get("status") == "available" and not _artifact_expired(artifact) and isinstance(artifact.get("output_items"), list):
        if key is not None:
            key["last_used_at"] = now_iso
            key["updated_at"] = now_iso
            _save("api_keys.json", api_keys)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "artifact": artifact,
            "article": {"id": article.get("id"), "title": article.get("title"), "language": article.get("language")},
            "topics": artifact.get("output_items", [])[:limit],
            "cached": True,
            "latency_ms": latency_ms
        }

    if artifact is None:
        artifact = {
            "id": _gen_id("da"),
            "client_id": client.get("id"),
            "article_id": article.get("id"),
            "artifact_type": "related_topics",
            "query": None,
            "section_title": None,
            "topic_within_article": None,
            "max_length": None,
            "count": limit,
            "status": "computing",
            "output_text": None,
            "output_items": None,
            "computed_at": None,
            "expires_at": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        derived.append(artifact)
    else:
        artifact["status"] = "computing"
        artifact["updated_at"] = now_iso
        artifact["error_message"] = None

    _save("derived_artifacts.json", derived)

    # Compute related topics from links and categories
    try:
        link_titles = []
        for l in (article.get("links") or []):
            if isinstance(l, dict):
                t = l.get("title")
                if isinstance(t, str) and t.strip():
                    link_titles.append(t.strip())
        cat_titles = []
        for c in (article.get("categories") or []):
            if isinstance(c, dict):
                t = c.get("title")
                if isinstance(t, str) and t.strip():
                    cat_titles.append(t.strip())

        seen = set()
        items = []

        # prioritize links
        for t in link_titles:
            nt = _normalize_title(t)
            if not nt or nt in seen:
                continue
            seen.add(nt)
            items.append({"topic": t, "normalized_title": nt, "reason": "linked_from_article"})
            if len(items) >= limit:
                break

        # then categories (strip "Category:" prefix)
        if len(items) < limit:
            for t in cat_titles:
                t2 = re.sub(r"^Category\s*:\s*", "", t, flags=re.I).strip()
                nt = _normalize_title(t2)
                if not nt or nt in seen:
                    continue
                seen.add(nt)
                items.append({"topic": t2, "normalized_title": nt, "reason": "article_category"})
                if len(items) >= limit:
                    break

        if not items:
            artifact["status"] = "error"
            artifact["error_message"] = "No related topics could be derived."
        else:
            artifact["output_items"] = items[:limit]
            artifact["status"] = "available"
            artifact["computed_at"] = now_iso
            artifact["expires_at"] = (now + datetime.timedelta(hours=24)).isoformat() + "Z"
            artifact["error_message"] = None
    except Exception as e:
        artifact["status"] = "error"
        artifact["error_message"] = f"Computation failed: {e.__class__.__name__}"

    artifact["updated_at"] = now_iso
    _save("derived_artifacts.json", derived)

    if artifact.get("status") != "available":
        return _err("CONFLICT", "Failed to derive related topics.", status=artifact.get("status"), error_message=artifact.get("error_message"))

    if key is not None:
        key["last_used_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "artifact": artifact,
        "article": {"id": article.get("id"), "title": article.get("title"), "language": article.get("language")},
        "topics": artifact.get("output_items", [])[:limit],
        "cached": False,
        "latency_ms": latency_ms
    }

