                "updated_at": now_iso,
            }
            articles.append(row)
            _save("articles.json", articles)
            return row

        existing_row["title"] = canonical_title or existing_row.get("title") or title.strip()
        existing_row["page_id"] = page_id if isinstance(page_id, int) else existing_row.get("page_id")
        existing_row["revision_id"] = revision_id if isinstance(revision_id, int) else existing_row.get("revision_id")
        if missing:
            existing_row["status"] = "missing"
            existing_row["sections"] = None
            existing_row["summary_text"] = None
            existing_row["fetched_at"] = None
            existing_row["expires_at"] = None
        elif error_message:
            existing_row["status"] = "error"
        else:
            existing_row["status"] = "available"
            existing_row["sections"] = sections
            existing_row["summary_text"] = summary_text
            existing_row["fetched_at"] = fetched_at
            existing_row["expires_at"] = expires_at
        existing_row["updated_at"] = now_iso
        _save("articles.json", articles)
        return existing_row

    article = None
    for r in articles:
        if r.get("language") == language and r.get("normalized_title") == norm_title:
            article = r
            break

    if article is None or article.get("status") in ("stale", "missing", "error") or _is_expired(article) or article.get("sections") is None:
        article = _refresh_article(article)

    if article.get("status") == "missing":
        return _err("NOT_FOUND", "Article not found on Wikipedia.", title=title, language=language)
    if article.get("status") != "available":
        return _err("CONFLICT", "Article is not available.", status=article.get("status"))

    sections = article.get("sections")
    if not isinstance(sections, list) or not sections:
        return _err("NOT_FOUND", "No retrievable section structure for this article.", title=article.get("title"), language=language)

    # mark key last_used_at on successful call
    if key is not None:
        key["last_used_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "article": {"id": article.get("id"), "title": article.get("title"), "language": article.get("language")},
        "sections": sections,
        "latency_ms": latency_ms
    }

def get_links(title, **_extra):
    import json, os, datetime, time, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _norm_title(t):
        t = t.strip().replace("_", " ")
        t = re.sub(r"\s+", " ", t)
        return t.lower()

    def _ensure_request_log_collection():
        # Observability: if no explicit request log collection exists in schema, use request_logs.json
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, client_id, api_key_id, status, latency_ms, meta=None):
        _ensure_request_log_collection()
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(_now().timestamp() * 1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": _iso(_now()),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            # don't fail the main request solely for logging persistence
            pass

    def _select_authorized_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None

        # Prefer a working active api_key for an active client; if none, allow internal context.
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if any(c.get("id") == cid and c.get("status") == "active" for c in clients):
                return {"client": next(c for c in clients if c.get("id") == cid), "api_key": k}

        # internal/ambient context (no api_key) still must correspond to an active client
        return {"client": active_clients[0], "api_key": None}

    def _enforce_quota(client, endpoint, api_key_id):
        # daily_request_limit applies to successful tool calls per UTC day.
        limit = client.get("daily_request_limit")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "Client daily_request_limit is invalid.")
        # Count successes today from request logs (fallback to 0 if unavailable)
        logs = _load("request_logs.json")
        now = _now()
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        successes = 0
        for r in logs:
            if r.get("client_id") != client.get("id"):
                continue
            if r.get("status") != "succeeded":
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= day_start and ts <= now:
                successes += 1
        if successes >= limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=limit, used=successes)
        return None

    def _needs_refresh(article):
        if not isinstance(article, dict):
            return True
        expires_at = _parse_dt(article.get("expires_at"))
        fetched_at = _parse_dt(article.get("fetched_at"))
        if article.get("status") in ("stale", "error", "missing"):
            # missing/error may be refreshed; stale should be refreshed
            return True
        if expires_at is None:
            return False
        now = _now()
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=datetime.timezone.utc)
        if fetched_at is not None and fetched_at.tzinfo is None:
            fetched_at = fetched_at.replace(tzinfo=datetime.timezone.utc)
        return expires_at <= now

    def _wikipedia_fetch(language, title_display):
        # Fetch summary and links in one pass using MediaWiki API.
        base = f"https://{language}.wikipedia.org/w/api.php"
        params = {
            "format": "json",
            "redirects": "1",
            "titles": title_display,
            "prop": "extracts|links|categories|revisions|info",
            "explaintext": "1",
            "exintro": "0",
            "exsectionformat": "plain",
            "plnamespace": "0",
            "pllimit": "max",
            "cllimit": "max",
            "rvprop": "ids",
            "inprop": "url",
        }

        def _req(p):
            url = base + "?" + urllib.parse.urlencode(p)
            with urllib.request.urlopen(url, timeout=20) as resp:
                raw = resp.read().decode("utf-8")
            return json.loads(raw)

        data = _req(params)
        if not isinstance(data, dict):
            return {"status": "error", "error_message": "Wikipedia response invalid."}

        pages = (data.get("query") or {}).get("pages")
        if not isinstance(pages, dict) or not pages:
            return {"status": "error", "error_message": "Wikipedia response missing pages."}

        page = next(iter(pages.values()))
        if page.get("missing") is not None:
            return {"status": "missing"}

        page_id = page.get("pageid")
        revs = page.get("revisions") or []
        revision_id = None
        if isinstance(revs, list) and revs:
            revision_id = revs[0].get("revid")

        extract = page.get("extract")
        if extract is None:
            extract = ""

        # links
        links = []
        pls = page.get("links") or []
        if isinstance(pls, list):
            for it in pls:
                t = it.get("title")
                if not isinstance(t, str) or not t.strip():
                    continue
                links.append(
                    {
                        "title": t,
                        "normalized_title": _norm_title(t),
                        "href": None,
                    }
                )

        # categories
        categories = []
        cls = page.get("categories") or []
        if isinstance(cls, list):
            for it in cls:
                t = it.get("title")
                if isinstance(t, str) and t.strip():
                    categories.append({"title": t})

        # sections: use parse API for sections
        sec_params = {"format": "json", "redirects": "1", "page": title_display, "action": "parse", "prop": "sections"}
        try:
            sec_data = _req(sec_params)
            sec_list = (((sec_data.get("parse") or {}).get("sections")) or [])
        except Exception:
            sec_list = []
        sections = []
        if isinstance(sec_list, list):
            for s in sec_list:
                try:
                    sections.append(
                        {
                            "index": int(s.get("index")) if str(s.get("index")).isdigit() else None,
                            "title": s.get("line") if isinstance(s.get("line"), str) else "",
                            "anchor": s.get("anchor") if isinstance(s.get("anchor"), str) else "",
                            "level": int(s.get("level")) if str(s.get("level")).isdigit() else None,
                        }
                    )
                except Exception:
                    continue
            sections = [x for x in sections if x.get("index") is not None and x.get("title")]

        # best-effort canonical title returned by Wikipedia
        canonical_title = page.get("title") if isinstance(page.get("title"), str) and page.get("title").strip() else title_display

        return {
            "status": "available",
            "title": canonical_title,
            "page_id": page_id if isinstance(page_id, int) and page_id > 0 else None,
            "revision_id": revision_id if isinstance(revision_id, int) and revision_id > 0 else None,
            "full_text": extract,
            "summary_text": None,  # not guaranteed here; keep null unless separately computed
            "sections": sections,
            "links": links,
            "categories": categories,
        }

    t0 = time.time()

    # Validate
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")

    ctx = _select_authorized_context()
    if ctx is None:
        _log("get_links", None, None, "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No authorized client context is available.")

    client = ctx["client"]
    api_key = ctx["api_key"]

    if api_key is not None and api_key.get("status") != "active":
        _log("get_links", client.get("id"), api_key.get("id"), "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is not active.")

    qerr = _enforce_quota(client, "get_links", api_key.get("id") if api_key else None)
    if qerr:
        _log("get_links", client.get("id"), api_key.get("id") if api_key else None, "quota_exceeded", int((time.time() - t0) * 1000))
        return qerr

    language = client.get("default_language")
    if not isinstance(language, str) or not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", language):
        _log("get_links", client.get("id"), api_key.get("id") if api_key else None, "failed", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Client default_language is invalid.")

    norm = _norm_title(title)

    articles = _load("articles.json")
    existing = None
    for a in articles:
        if a.get("language") == language and a.get("normalized_title") == norm:
            existing = a
            break

    # refresh if needed
    refreshed = False
    if existing is None or existing.get("links") is None or _needs_refresh(existing):
        # If exists and needs refresh, move to stale when appropriate
        now = _now()
        if existing is not None:
            prev_status = existing.get("status")
            if prev_status == "available":
                # legal transition available -> stale
                existing["status"] = "stale"
            existing["updated_at"] = _iso(now)
            _save("articles.json", articles)

        try:
            fetched = _wikipedia_fetch(language, existing.get("title") if isinstance(existing, dict) and existing.get("title") else title.strip())
        except Exception:
            fetched = {"status": "error", "error_message": "Wikipedia fetch failed."}

        refreshed = True
        now = _now()

        if existing is None:
            # create new article cache row
            aid = f"art_{int(now.timestamp()*1000)}_{len(articles)+1}"
            existing = {
                "id": aid,
                "language": language,
                "title": title.strip(),
                "normalized_title": norm,
                "page_id": None,
                "revision_id": None,
                "status": "error",
                "full_text": None,
                "summary_text": None,
                "sections": None,
                "links": None,
                "categories": None,
                "fetched_at": None,
                "expires_at": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            articles.append(existing)

        if fetched.get("status") == "missing":
            # stale/missing transitions allowed
            cur = existing.get("status")
            if cur not in ("stale", "missing", "error", "available"):
                cur = "stale"
            # transition to missing if legal
            if cur in ("stale",):
                existing["status"] = "missing"
            else:
                # if from available, legal available->error only; but refresh can yield missing; treat as error to respect lifecycle
                existing["status"] = "error"
                existing["error_message"] = "Wikipedia page missing."
            existing["fetched_at"] = _iso(now)
            existing["expires_at"] = _iso(now + datetime.timedelta(hours=6))
            existing["links"] = []
            existing["updated_at"] = _iso(now)
            _save("articles.json", articles)
        elif fetched.get("status") == "available":
            # transition to available if legal from stale/missing/error
            existing["status"] = "available"
            existing["title"] = fetched.get("title") or existing.get("title") or title.strip()
            existing["page_id"] = fetched.get("page_id")
            existing["revision_id"] = fetched.get("revision_id")
            existing["full_text"] = fetched.get("full_text")
            existing["sections"] = fetched.get("sections")
            existing["links"] = fetched.get("links")
            existing["categories"] = fetched.get("categories")
            existing["fetched_at"] = _iso(now)
            existing["expires_at"] = _iso(now + datetime.timedelta(hours=24))
            existing["updated_at"] = _iso(now)
            _save("articles.json", articles)
        else:
            existing["status"] = "error"
            existing["error_message"] = fetched.get("error_message") or "Unknown fetch error."
            existing["updated_at"] = _iso(now)
            # keep previous cached data if any
            existing["expires_at"] = _iso(now + datetime.timedelta(hours=1))
            _save("articles.json", articles)

    # post-refresh checks
    if existing.get("status") == "missing":
        _log("get_links", client.get("id"), api_key.get("id") if api_key else None, "failed", int((time.time() - t0) * 1000), meta={"refreshed": refreshed})
        return _err("NOT_FOUND", "Wikipedia page does not exist.", title=title)

    if existing.get("status") != "available" or existing.get("links") is None:
        _log("get_links", client.get("id"), api_key.get("id") if api_key else None, "failed", int((time.time() - t0) * 1000), meta={"refreshed": refreshed})
        return _err("CONFLICT", "Article links are not available.", article_status=existing.get("status"))

    # update key last_used_at on success (do not attempt to validate secret token against token_hash)
    if api_key is not None:
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = _iso(_now())
                k["updated_at"] = _iso(_now())
                break
        _save("api_keys.json", keys)

    latency = int((time.time() - t0) * 1000)
    _log("get_links", client.get("id"), api_key.get("id") if api_key else None, "succeeded", latency, meta={"refreshed": refreshed})

    return {
        "article": {
            "id": existing.get("id"),
            "language": existing.get("language"),
            "title": existing.get("title"),
            "normalized_title": existing.get("normalized_title"),
            "page_id": existing.get("page_id"),
            "revision_id": existing.get("revision_id"),
            "status": existing.get("status"),
            "fetched_at": existing.get("fetched_at"),
            "expires_at": existing.get("expires_at"),
        },
        "links": existing.get("links") or [],
        "count": len(existing.get("links") or []),
    }

def list_search_queries(status=None, language=None, query_contains=None, requested_after=None, requested_before=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log_collection():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, client_id, api_key_id, status_s, latency_ms, meta=None):
        _ensure_request_log_collection()
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(_now().timestamp() * 1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "ts": _iso(_now()),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _select_authorized_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if any(c.get("id") == cid and c.get("status") == "active" for c in clients):
                return {"client": next(c for c in clients if c.get("id") == cid), "api_key": k}
        return {"client": active_clients[0], "api_key": None}

    def _enforce_quota(client):
        limit = client.get("daily_request_limit")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "Client daily_request_limit is invalid.")
        logs = _load("request_logs.json")
        now = _now()
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        successes = 0
        for r in logs:
            if r.get("client_id") != client.get("id"):
                continue
            if r.get("status") != "succeeded":
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= day_start and ts <= now:
                successes += 1
        if successes >= limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=limit, used=successes)
        return None

    t0 = time.time()

    # defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 20

    # validate
    allowed_status = {"queued", "running", "succeeded", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if language is not None:
        if not isinstance(language, str) or not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", language):
            return _err("VALIDATION_ERROR", "Invalid language filter.")
    if query_contains is not None and not isinstance(query_contains, str):
        return _err("VALIDATION_ERROR", "query_contains must be a string.")
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")

    ra = _parse_dt(requested_after) if requested_after is not None else None
    rb = _parse_dt(requested_before) if requested_before is not None else None
    if requested_after is not None and ra is None:
        return _err("VALIDATION_ERROR", "requested_after must be a valid RFC3339 datetime.")
    if requested_before is not None and rb is None:
        return _err("VALIDATION_ERROR", "requested_before must be a valid RFC3339 datetime.")
    if ra and rb:
        # if both present ensure window order
        ara = ra.astimezone(datetime.timezone.utc) if ra.tzinfo else ra.replace(tzinfo=datetime.timezone.utc)
        arb = rb.astimezone(datetime.timezone.utc) if rb.tzinfo else rb.replace(tzinfo=datetime.timezone.utc)
        if arb < ara:
            return _err("VALIDATION_ERROR", "requested_before must be >= requested_after.")

    ctx = _select_authorized_context()
    if ctx is None:
        _log("list_search_queries", None, None, "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No authorized client context is available.")
    client = ctx["client"]
    api_key = ctx["api_key"]

    if api_key is not None and api_key.get("status") != "active":
        _log("list_search_queries", client.get("id"), api_key.get("id"), "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is not active.")

    qerr = _enforce_quota(client)
    if qerr:
        _log("list_search_queries", client.get("id"), api_key.get("id") if api_key else None, "quota_exceeded", int((time.time() - t0) * 1000))
        return qerr

    rows = _load("search_queries.json")

    def visible(r):
        if r.get("client_id") != client.get("id"):
            return False
        # if authenticated via key, only show jobs created by that key (or internal/null if desired?)
        # business description: "by your API key/client" => with key, scope to client (not strictly key).
        return True

    out = []
    for r in rows:
        if not isinstance(r, dict) or not visible(r):
            continue
        if status is not None and r.get("status") != status:
            continue
        if language is not None and r.get("language") != language:
            continue
        if query_contains is not None:
            q = r.get("query")
            if not isinstance(q, str) or query_contains.lower() not in q.lower():
                continue
        rat = _parse_dt(r.get("requested_at"))
        if ra is not None:
            if rat is None:
                continue
            rr = rat.astimezone(datetime.timezone.utc) if rat.tzinfo else rat.replace(tzinfo=datetime.timezone.utc)
            aa = ra.astimezone(datetime.timezone.utc) if ra.tzinfo else ra.replace(tzinfo=datetime.timezone.utc)
            if rr < aa:
                continue
        if rb is not None:
            if rat is None:
                continue
            rr = rat.astimezone(datetime.timezone.utc) if rat.tzinfo else rat.replace(tzinfo=datetime.timezone.utc)
            bb = rb.astimezone(datetime.timezone.utc) if rb.tzinfo else rb.replace(tzinfo=datetime.timezone.utc)
            if rr > bb:
                continue
        out.append(r)

    # newest first by requested_at then created_at
    def _sort_key(r):
        ra2 = _parse_dt(r.get("requested_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if ra2.tzinfo is None:
            ra2 = ra2.replace(tzinfo=datetime.timezone.utc)
        return ra2

    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = out[start:end]
    has_more = end < total

    # update last_used_at on success
    if api_key is not None:
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = _iso(_now())
                k["updated_at"] = _iso(_now())
                break
        _save("api_keys.json", keys)

    latency = int((time.time() - t0) * 1000)
    _log("list_search_queries", client.get("id"), api_key.get("id") if api_key else None, "succeeded", latency, meta={"returned": len(page_items), "total": total})

    return {
        "data": page_items,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
        },
    }

def get_search_query(id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    endpoint = "get_search_query"

    # ---- request logging / quota helpers (must persist observable dynamics) ----
    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _utc_day_str(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _count_success_today_for_client(client_id):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return 0
        today = _utc_day_str(now)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            if r.get("status") != "succeeded":
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if _utc_day_str(ts) == today:
                c += 1
        return c

    def _enforce_daily_quota(client_row):
        limit = client_row.get("daily_request_limit")
        if not isinstance(limit, int):
            try:
                limit = int(limit)
            except Exception:
                return None  # if bad data in store, do not block; still log later
        if limit < 0:
            return None
        used = _count_success_today_for_client(client_row.get("id"))
        if used >= limit:
            return _err(
                "QUOTA_EXCEEDED",
                f"Rate limited: daily quota exceeded for client_id {client_row.get('id')}.",
                client_id=client_row.get("id"),
                daily_request_limit=limit,
                used_today=used,
            )
        return None

    def _log(client_id, api_key_id, status, meta=None):
        try:
            _ensure_request_logs()
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((time.time() - started) * 1000)
            row = {
                "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(6)}",
                "endpoint": endpoint,
                "client_id": client_id,
                "api_key_id": api_key_id,
                "status": status,
                "latency_ms": latency_ms,
                "ts": now_iso,
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            # Never raise; logging failures shouldn't break the tool.
            return

    # ---- input validation ----
    if not isinstance(id, str) or not id.strip():
        # log with best-effort resolved context later; for now log without context
        _log(None, None, "failed", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    # ---- load data ----
    sq = _load("search_queries.json")
    if not isinstance(sq, list):
        sq = []

    # Find the search query row by id. Note: callers may pass an id that is not a search_query id
    # (audit shows an api_client id was passed). Do not "validate prefix"; just lookup.
    row = None
    for r in sq:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break

    # Resolve authorization context: ambient auth means we must find some valid active client+key
    # combination to serve the call. If the row exists, prefer its owning client_id; otherwise pick any active.
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    if not isinstance(clients, list):
        clients = []
    if not isinstance(keys, list):
        keys = []

    def _find_active_key_for_client(cid):
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("client_id") != cid:
                continue
            if k.get("status") == "active":
                return k
        return None

    chosen_client = None
    chosen_key = None

    if isinstance(row, dict):
        cid = row.get("client_id")
        if isinstance(cid, str) and cid:
            for c in clients:
                if isinstance(c, dict) and c.get("id") == cid and c.get("status") == "active":
                    k = _find_active_key_for_client(cid)
                    if k is not None:
                        chosen_client = c
                        chosen_key = k
                        break

    if chosen_client is None:
        # fallback: any active client with an active key
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            k = _find_active_key_for_client(c.get("id"))
            if k is None:
                continue
            chosen_client = c
            chosen_key = k
            break

    if chosen_client is None:
        # No workable authenticated context exists in the store
        _log(None, None, "failed", {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authorized API client/key context available to serve this request.")

    client_id = chosen_client.get("id")
    api_key_id = chosen_key.get("id") if isinstance(chosen_key, dict) else None

    # If row exists but belongs to a different client_id than our chosen context and we can't
    # establish a working context for that row's client, treat as NOT_FOUND (not visible).
    if isinstance(row, dict):
        row_cid = row.get("client_id")
        if isinstance(row_cid, str) and row_cid and row_cid != client_id:
            # try to switch to that client if it is active and has active key
            switched = False
            for c in clients:
                if isinstance(c, dict) and c.get("id") == row_cid and c.get("status") == "active":
                    k = _find_active_key_for_client(row_cid)
                    if k is not None:
                        chosen_client = c
                        chosen_key = k
                        client_id = row_cid
                        api_key_id = k.get("id")
                        switched = True
                        break
            if not switched:
                _log(client_id, api_key_id, "failed", {"error_code": "NOT_FOUND", "requested_id": id})
                return _err("NOT_FOUND", "Search query job not found.", id=id)

    # Enforce key/client status rule (active client and active key required)
    if chosen_client.get("status") != "active" or not (isinstance(chosen_key, dict) and chosen_key.get("status") == "active"):
        _log(client_id, api_key_id, "failed", {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Rejected: API key is inactive or expired for this client.")

    # Enforce daily quota (applies to all tool calls)
    quota_err = _enforce_daily_quota(chosen_client)
    if quota_err:
        _log(client_id, api_key_id, "failed", {"error_code": "QUOTA_EXCEEDED"})
        return quota_err

    # If still not found, return NOT_FOUND (as required by tool description)
    if row is None:
        _log(client_id, api_key_id, "failed", {"error_code": "NOT_FOUND", "requested_id": id})
        return _err("NOT_FOUND", "Search query job not found.", id=id)

    # Update last_used_at for the key on successful auth (best-effort)
    if isinstance(chosen_key, dict):
        for i, k in enumerate(keys):
            if isinstance(k, dict) and k.get("id") == chosen_key.get("id"):
                k2 = dict(k)
                k2["last_used_at"] = now_iso
                k2["updated_at"] = now_iso
                keys[i] = k2
                try:
                    _save("api_keys.json", keys)
                except Exception:
                    pass
                break

    # Success response
    _log(client_id, api_key_id, "succeeded", {"search_query_id": id})

    # Return the stored job row (no fabrication)
    return {
        "search_query": row,
        "meta": {
            "id": id,
            "client_id": row.get("client_id"),
            "status": row.get("status"),
        },
    }

def list_derived_artifacts(artifact_type=None, status=None, article_id=None, query=None, section_title=None, topic_within_article=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log_collection():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, client_id, api_key_id, status_s, latency_ms, meta=None):
        _ensure_request_log_collection()
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(_now().timestamp() * 1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "ts": _iso(_now()),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _select_authorized_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if any(c.get("id") == cid and c.get("status") == "active" for c in clients):
                return {"client": next(c for c in clients if c.get("id") == cid), "api_key": k}
        return {"client": active_clients[0], "api_key": None}

    def _enforce_quota(client):
        limit = client.get("daily_request_limit")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "Client daily_request_limit is invalid.")
        logs = _load("request_logs.json")
        now = _now()
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        successes = 0
        for r in logs:
            if r.get("client_id") != client.get("id"):
                continue
            if r.get("status") != "succeeded":
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= day_start and ts <= now:
                successes += 1
        if successes >= limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=limit, used=successes)
        return None

    t0 = time.time()

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20

    allowed_types = {"query_summary", "section_summary", "key_facts", "related_topics"}
    allowed_status = {"computing", "available", "stale", "error"}

    if artifact_type is not None:
        if not isinstance(artifact_type, str) or artifact_type not in allowed_types:
            return _err("VALIDATION_ERROR", "Invalid artifact_type.")
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.")
    if article_id is not None and (not isinstance(article_id, str) or not article_id.strip()):
        return _err("VALIDATION_ERROR", "article_id must be a non-empty string.")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    if section_title is not None and not isinstance(section_title, str):
        return _err("VALIDATION_ERROR", "section_title must be a string.")
    if topic_within_article is not None and not isinstance(topic_within_article, str):
        return _err("VALIDATION_ERROR", "topic_within_article must be a string.")
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")

    ctx = _select_authorized_context()
    if ctx is None:
        _log("list_derived_artifacts", None, None, "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No authorized client context is available.")
    client = ctx["client"]
    api_key = ctx["api_key"]

    if api_key is not None and api_key.get("status") != "active":
        _log("list_derived_artifacts", client.get("id"), api_key.get("id"), "unauthorized", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is not active.")

    qerr = _enforce_quota(client)
    if qerr:
        _log("list_derived_artifacts", client.get("id"), api_key.get("id") if api_key else None, "quota_exceeded", int((time.time() - t0) * 1000))
        return qerr

    rows = _load("derived_artifacts.json")
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client.get("id"):
            continue
        if artifact_type is not None and r.get("artifact_type") != artifact_type:
            continue
        if status is not None and r.get("status") != status:
            continue
        if article_id is not None and r.get("article_id") != article_id:
            continue
        if query is not None and (r.get("query") or "") != query:
            continue
        if section_title is not None and (r.get("section_title") or "") != section_title:
            continue
        if topic_within_article is not None and (r.get("topic_within_article") or "") != topic_within_article:
            continue
        out.append(r)

    # newest first by updated_at then created_at
    def _sort_key(r):
        dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = out[start:end]
    has_more = end < total

    if api_key is not None:
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = _iso(_now())
                k["updated_at"] = _iso(_now())
                break
        _save("api_keys.json", keys)

    latency = int((time.time() - t0) * 1000)
    _log("list_derived_artifacts", client.get("id"), api_key.get("id") if api_key else None, "succeeded", latency, meta={"returned": len(page_items), "total": total})

    return {
        "data": page_items,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
        },
    }

def refresh_article(title, language=None, force=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0532000" if __import__("os").path.isdir("./environment_mix/0532000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, client_id, api_key_id, status, latency_ms, meta=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(6)}",
            "endpoint": endpoint,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": now_iso,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        return bool(exp and exp <= now)

    def _normalize_title(t):
        t = t.strip().replace("_", " ")
        t = re.sub(r"\s+", " ", t)
        return t.lower()

    def _pick_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if c.get("status") == "active"]
        if not active_clients:
            return None, None
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            c = next((x for x in active_clients if x.get("id") == cid), None)
            if c:
                return c, k
        return active_clients[0], None

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _enforce_quota(client_row):
        limit_daily = client_row.get("daily_request_limit")
        if not isinstance(limit_daily, int) or limit_daily < 0:
            return _err("UNAUTHORIZED", "Client is not configured with a valid daily_request_limit.")
        day = _utc_day(now)
        total_success = 0
        logs = _load("request_logs.json")
        if isinstance(logs, list) and logs:
            for r in logs:
                if r.get("client_id") != client_row.get("id"):
                    continue
                ts = _parse_dt(r.get("ts"))
                if not ts or _utc_day(ts) != day:
                    continue
                if r.get("status") == "succeeded":
                    total_success += 1
        else:
            # fallback minimal
            sq = _load("search_queries.json")
            if isinstance(sq, list):
                for r in sq:
                    if r.get("client_id") == client_row.get("id") and r.get("status") == "succeeded":
                        ts = _parse_dt(r.get("requested_at"))
                        if ts and _utc_day(ts) == day:
                            total_success += 1
        if total_success >= limit_daily:
            return _err("QUOTA_EXCEEDED", f"Rate limited: daily quota exceeded for client_id {client_row.get('id')}.",
                        client_id=client_row.get("id"), daily_request_limit=limit_daily, day=day, successful_calls=total_success)
        return None

    # validate
    if not isinstance(title, str) or not title.strip():
        e = _err("VALIDATION_ERROR", "title must be a non-empty string.")
        _log("refresh_article", None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e
    if language is not None:
        if not isinstance(language, str) or not re.match(r"^[a-z]{2,3}(-[a-z0-9]+)?$", language.strip()):
            e = _err("VALIDATION_ERROR", "language must match regex '^[a-z]{2,3}(-[a-z0-9]+)?$'.")
            _log("refresh_article", None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
            return e
    if force is None:
        force = True
    if not isinstance(force, bool):
        e = _err("VALIDATION_ERROR", "force must be a boolean.")
        _log("refresh_article", None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    client, key = _pick_context()
    if not client:
        e = _err("UNAUTHORIZED", "No active API client is available for this request.")
        _log("refresh_article", None, None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # quota gate
    qerr = _enforce_quota(client)
    if qerr:
        _log("refresh_article", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": qerr["error"]})
        return qerr

    lang = (language.strip() if isinstance(language, str) and language.strip() else client.get("default_language")) or "en"
    ntitle = _normalize_title(title)

    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []

    existing = next((a for a in articles if a.get("language") == lang and a.get("normalized_title") == ntitle), None)
    if existing and not force and existing.get("status") == "available" and not _is_expired(existing):
        _log("refresh_article", client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000,
             {"article_id": existing.get("id"), "refreshed": False})
        return {"article": existing, "refreshed": False}

    # Offline "refetch": we cannot call Wikipedia; instead, transition cache state using available local info.
    # This must not fail spuriously with network errors.
    def _transition_ok(frm, to):
        transitions = {
            "available": {"stale", "error"},
            "stale": {"available", "missing", "error"},
            "missing": {"available", "error"},
            "error": {"stale", "available"},
        }
        return to in transitions.get(frm, set())

    def _gen_id():
        return f"wiki_art_{secrets.token_hex(12)}"

    if not existing:
        # if we cannot resolve page in local datastore, treat as NOT_FOUND per tool description
        e = _err("NOT_FOUND", "The page could not be resolved.", title=title, language=lang)
        _log("refresh_article", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    # mark stale if not already stale (legal transition from available->stale, error->stale); otherwise keep
    if existing.get("status") != "stale":
        if _transition_ok(existing.get("status"), "stale"):
            existing["status"] = "stale"
        # if illegal (e.g., computing doesn't exist here), ignore and proceed

    # "refetch" result decision: if record has some text/summary, make it available; else missing.
    has_content = isinstance(existing.get("full_text"), str) and existing.get("full_text").strip()
    has_summary = isinstance(existing.get("summary_text"), str) and existing.get("summary_text").strip()
    target_status = "available" if (has_content or has_summary) else "missing"

    if not _transition_ok(existing.get("status"), target_status) and existing.get("status") != target_status:
        e = _err("INVALID_TRANSITION", f"Illegal status transition from {existing.get('status')} to {target_status}.",
                 from_status=existing.get("status"), to_status=target_status)
        _log("refresh_article", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    existing["status"] = target_status
    existing["fetched_at"] = now_iso if target_status == "available" else existing.get("fetched_at")
    # refresh expiry window (serve as cache dynamics)
    existing["expires_at"] = (now + datetime.timedelta(hours=24)).isoformat().replace("+00:00", "Z")
    existing["updated_at"] = now_iso
    if not existing.get("created_at"):
        existing["created_at"] = now_iso
    if not existing.get("id"):
        existing["id"] = _gen_id()
    # keep canonical/display title if already present; otherwise store request title
    if not existing.get("title"):
        existing["title"] = title
    existing["normalized_title"] = ntitle
    existing["language"] = lang

    try:
        _save("articles.json", articles)
    except Exception:
        e = _err("CONFLICT", "Failed to persist refreshed article.")
        _log("refresh_article", client.get("id"), key.get("id") if key else None, "failed", (time.time() - started) * 1000, {"error": e["error"]})
        return e

    _log("refresh_article", client.get("id"), key.get("id") if key else None, "succeeded", (time.time() - started) * 1000,
         {"article_id": existing.get("id"), "refreshed": True, "status": existing.get("status")})
    return {"article": existing, "refreshed": True}
